FILES = json.loads('{"src/skillsgap/demand.py": "\\"\\"\\"Demand-side parsers (job postings). Parsers are pure functions of HTML -> records,\\nso they can be unit-tested on saved pages and re-run from cache without hitting the site.\\"\\"\\"\\nimport logging\\nimport re\\nfrom urllib.parse import urljoin\\n\\nfrom bs4 import BeautifulSoup\\n\\nfrom .schema import estimate_posted_date, make_record\\n\\nlog = logging.getLogger(\\"skillsgap.demand\\")\\n_POSTED = re.compile(r\\"^(today|yesterday|\\\\d+\\\\s+(day|week|month|year)s?\\\\s+ago)$\\", re.I)\\n\\n\\ndef parse_brightermonday_listing(html, page_url, retrieved_at, method=\\"http_get\\"):\\n    \\"\\"\\"Parse a BrighterMonday results page. Strategy: every <a href*=\'/listings/\'> is a\\n    posting; the card text around it supplies employer, location, posted age, job function.\\n    Returns (records, failures). Selectors are deliberately structure-light because the\\n    live markup must be validated on the first live run (see docs/DATA_QUALITY_MEMO).\\"\\"\\"\\n    soup = BeautifulSoup(html, \\"lxml\\")\\n    records, failures, seen = [], [], set()\\n    for a in soup.select(\\"a[href*=\'/listings/\']\\"):\\n        href = urljoin(page_url, a.get(\\"href\\", \\"\\"))\\n        title = a.get_text(\\" \\", strip=True)\\n        if not title or href in seen:\\n            continue\\n        seen.add(href)\\n        card = a\\n        for _ in range(4):  # climb to the enclosing card, but never into a container\\n            par = card.parent  # that holds more than one distinct listing (would mix postings)\\n            if par is None:\\n                break\\n            hrefs = {urljoin(page_url, x.get(\\"href\\", \\"\\")) for x in par.select(\\"a[href*=\'/listings/\']\\")}\\n            if len(hrefs) > 1:\\n                break\\n            card = par\\n            if len(card.get_text(\\" \\", strip=True)) > len(title) + 20:\\n                break\\n        lines = [s.strip() for s in card.get_text(\\"\\\\n\\", strip=True).split(\\"\\\\n\\") if s.strip()]\\n        lines = [l for l in lines if l != title]\\n        posted = next((l for l in lines if _POSTED.match(l)), \\"\\")\\n        func = next((re.sub(r\\"^Job Function\\\\s*:\\\\s*\\", \\"\\", l, flags=re.I)\\n                     for l in lines if l.lower().startswith(\\"job function\\")), \\"\\")\\n        rest = [l for l in lines if l != posted and not l.lower().startswith(\\"job function\\")]\\n        employer = rest[0] if rest else \\"\\"\\n        location = rest[1] if len(rest) > 1 else \\"\\"\\n        if not employer:\\n            failures.append({\\"url\\": href, \\"reason\\": \\"employer_not_found\\"})\\n        records.append(make_record(\\n            \\"demand\\", \\"brightermonday\\", page_url, retrieved_at, method,\\n            id_parts=[href], raw_for_hash=card.get_text(\\" \\", strip=True),\\n            record_url=href, title=title, employer=employer, location=location,\\n            posted_text=posted, posted_date_est=estimate_posted_date(posted, retrieved_at),\\n            function_raw=func))\\n    if not records:\\n        failures.append({\\"url\\": page_url, \\"reason\\": \\"no_listing_links_found\\"})\\n    return records, failures\\n\\n\\ndef parse_district_advert(html, page_url, retrieved_at, source=\\"district_adverts\\", method=\\"http_get\\"):\\n    \\"\\"\\"Parse a district service commission advert page: a table of posts + a deadline sentence.\\"\\"\\"\\n    soup = BeautifulSoup(html, \\"lxml\\")\\n    text = soup.get_text(\\" \\", strip=True)\\n    m = re.search(r\\"not later than\\\\s+([^.,;]+?\\\\d{4})\\", text, re.I)\\n    deadline = m.group(1).strip() if m else \\"\\"\\n    records, failures = [], []\\n    for table in soup.find_all(\\"table\\"):\\n        rows = table.find_all(\\"tr\\")\\n        if not rows:\\n            continue\\n        head = [c.get_text(\\" \\", strip=True).lower() for c in rows[0].find_all([\\"th\\", \\"td\\"])]\\n        idx = {k: next((i for i, h in enumerate(head) if k in h), None)\\n               for k in (\\"department\\", \\"job title\\", \\"ref\\", \\"salary\\", \\"vacanc\\")}\\n        if idx[\\"job title\\"] is None:\\n            continue\\n        for r in rows[1:]:\\n            c = [x.get_text(\\" \\", strip=True) for x in r.find_all([\\"td\\", \\"th\\"])]\\n            if len(c) <= idx[\\"job title\\"] or not c[idx[\\"job title\\"]]:\\n                failures.append({\\"url\\": page_url, \\"reason\\": \\"row_without_title\\"})\\n                continue\\n            g = lambda k: c[idx[k]] if idx[k] is not None and idx[k] < len(c) else \\"\\"\\n            records.append(make_record(\\n                \\"demand\\", source, page_url, retrieved_at, method,\\n                id_parts=[page_url, g(\\"ref\\"), g(\\"job title\\")], raw_for_hash=\\" \\".join(c),\\n                record_url=page_url, title=g(\\"job title\\"), employer=_host_label(page_url),\\n                department=g(\\"department\\"), ref_no=g(\\"ref\\"), salary_scale=g(\\"salary\\"),\\n                vacancies=g(\\"vacanc\\"), deadline=deadline, function_raw=g(\\"department\\")))\\n    if not records:  # advert typed as tab-separated text lines (br-separated), not an HTML table\\n        row_re = re.compile(r\\"^\\\\s*\\\\d+\\\\.?\\\\s*(.+?)\\\\s+([A-Z0-9]+(?:/[A-Z0-9]+)+)\\\\s+(.+?)\\\\s+(U\\\\d+[A-Z]?)\\\\s+(\\\\d+)\\\\s*$\\")\\n        for ln in soup.get_text(\\"\\\\n\\").splitlines():\\n            m = row_re.match(ln.replace(\\"\\\\xa0\\", \\" \\"))\\n            if not m:\\n                continue\\n            dept, ref, title, scale, vac = [re.sub(r\\"\\\\s+\\", \\" \\", x).strip() for x in m.groups()]\\n            records.append(make_record(\\n                \\"demand\\", source, page_url, retrieved_at, method,\\n                id_parts=[page_url, ref, title], raw_for_hash=ln,\\n                record_url=page_url, title=title, employer=_host_label(page_url),\\n                department=dept, ref_no=ref, salary_scale=scale, vacancies=vac,\\n                deadline=deadline, function_raw=dept))\\n    if not records:\\n        failures.append({\\"url\\": page_url, \\"reason\\": \\"no_vacancy_table_found\\"})\\n    return records, failures\\n\\n\\ndef _host_label(url):\\n    from urllib.parse import urlparse\\n    return urlparse(url).netloc\\n", "src/skillsgap/pipeline.py": "\\"\\"\\"ETL entry point.   python -m skillsgap.pipeline --out out/            (fresh run)\\n                      python -m skillsgap.pipeline --out out/ --offline   (re-run from cache only)\\nExtract (polite fetch + cache) -> Transform (pure parsers) -> Load (CSV/JSON + quality report + manifest).\\nA source runs only if enabled in config/sources.yaml AND has an approval string recorded there.\\"\\"\\"\\nimport argparse\\nimport csv\\nimport hashlib\\nimport json\\nimport logging\\nimport sys\\nfrom pathlib import Path\\n\\nfrom . import __version__\\nfrom .config import load_config, user_agent\\nfrom .demand import parse_brightermonday_listing, parse_district_advert\\nfrom .http import PoliteClient, RobotsDisallowed\\nfrom .quality import report\\nfrom .schema import now_iso, write_csv, write_json\\nfrom .supply import parse_graduation_pdf\\n\\nlog = logging.getLogger(\\"skillsgap.pipeline\\")\\n\\n\\ndef run(cfg, out_dir, only=None, offline=False, client=None):\\n    out = Path(out_dir)\\n    (out / \\"logs\\").mkdir(parents=True, exist_ok=True)\\n    fh = logging.FileHandler(out / \\"logs\\" / \\"pipeline.log\\", encoding=\\"utf-8\\")\\n    fh.setFormatter(logging.Formatter(\\"%(asctime)s %(levelname)s %(name)s %(message)s\\"))\\n    logging.getLogger().addHandler(fh)\\n    logging.getLogger().setLevel(logging.INFO)\\n    client = client or PoliteClient(cfg, user_agent(cfg), cfg[\\"_root\\"], offline=offline)\\n    lim = cfg[\\"limits\\"]\\n    started = now_iso()\\n    records, failures, compliance = [], [], []\\n\\n    def gate(name, scfg):\\n        if only and name not in only:\\n            return False\\n        if not scfg.get(\\"enabled\\") or not scfg.get(\\"approval\\"):\\n            log.warning(\\"SKIP %s: not enabled or no approval recorded\\", name)\\n            return False\\n        return True\\n\\n    for name, scfg in cfg[\\"sources\\"].items():\\n        if not gate(name, scfg):\\n            continue\\n        n_before = len(records)\\n        try:\\n            if name == \\"brightermonday\\":\\n                for page in range(1, lim[\\"max_pages_per_source\\"] + 1):\\n                    url = scfg[\\"listing_url\\"] + (\\"\\" if page == 1 else f\\"?page={page}\\")\\n                    body, meta = client.get(url)\\n                    ts = now_iso()\\n                    recs, fails = parse_brightermonday_listing(body.decode(\\"utf-8\\", \\"replace\\"), url, ts,\\n                                                              \\"cache_replay\\" if meta[\\"from_cache\\"] else \\"http_get\\")\\n                    records += recs; failures += fails\\n                    if not recs or len(records) - n_before >= lim[\\"max_records_per_source\\"]:\\n                        break\\n            elif name == \\"district_adverts\\":\\n                for url in scfg[\\"urls\\"]:\\n                    body, meta = client.get(url)\\n                    recs, fails = parse_district_advert(body.decode(\\"utf-8\\", \\"replace\\"), url, now_iso(),\\n                                                       method=\\"cache_replay\\" if meta[\\"from_cache\\"] else \\"http_get\\")\\n                    records += recs; failures += fails\\n            elif name == \\"graduation_lists\\":\\n                for item in scfg[\\"lists\\"]:\\n                    if item.get(\\"enabled\\") is False:\\n                        log.info(\\"SKIP list %s (disabled in config)\\", item[\\"name\\"])\\n                        continue\\n                    body, meta = client.get(item[\\"url\\"])\\n                    recs, fails = parse_graduation_pdf(body, item, now_iso(),\\n                                                       \\"cache_replay\\" if meta[\\"from_cache\\"] else \\"http_get\\")\\n                    records += recs; failures += fails\\n        except RobotsDisallowed as e:\\n            failures.append({\\"url\\": str(e), \\"reason\\": \\"robots_disallowed\\"})\\n        except Exception as e:  # keep going: one failing source must not stop the run\\n            log.exception(\\"source %s failed\\", name)\\n            failures.append({\\"url\\": name, \\"reason\\": f\\"collection_error: {e}\\"})\\n        compliance.append({\\"source\\": name, \\"approval\\": scfg.get(\\"approval\\"), \\"tos_note\\": scfg.get(\\"tos_note\\", \\"\\"),\\n                           \\"records_collected\\": len(records) - n_before, \\"rate_limit_s\\": cfg[\\"http\\"][\\"min_delay_seconds\\"],\\n                           \\"user_agent\\": client.ua})\\n\\n    seen_ids, unique = set(), []\\n    for r in records:  # listings shift between pages, so the same posting can appear twice\\n        if r[\\"record_id\\"] in seen_ids:\\n            continue\\n        seen_ids.add(r[\\"record_id\\"]); unique.append(r)\\n    dup_dropped = len(records) - len(unique)\\n    records[:] = unique\\n    write_csv(records, out / \\"dataset.csv\\")\\n    write_json(records, out / \\"dataset.json\\")\\n    rep = report(records, failures, client.stats)\\n    rep[\\"duplicates_dropped_before_write\\"] = dup_dropped\\n    (out / \\"quality_report.json\\").write_text(json.dumps(rep, indent=2), encoding=\\"utf-8\\")\\n    with open(out / \\"compliance_run_log.csv\\", \\"w\\", newline=\\"\\", encoding=\\"utf-8\\") as f:\\n        w = csv.DictWriter(f, fieldnames=list(compliance[0].keys()) if compliance else [\\"source\\"])\\n        w.writeheader(); w.writerows(compliance)\\n    manifest = {\\"pipeline_version\\": __version__, \\"started_at\\": started, \\"finished_at\\": now_iso(),\\n                \\"offline\\": offline, \\"config_sha256\\": hashlib.sha256(json.dumps(\\n                    {k: v for k, v in cfg.items() if k != \\"_root\\"}, sort_keys=True).encode()).hexdigest(),\\n                \\"records\\": len(records)}\\n    (out / \\"run_manifest.json\\").write_text(json.dumps(manifest, indent=2), encoding=\\"utf-8\\")\\n    return records, failures, rep\\n\\n\\ndef main(argv=None):\\n    ap = argparse.ArgumentParser(description=\\"Skills-Gap ETL pipeline v1\\")\\n    ap.add_argument(\\"--config\\"); ap.add_argument(\\"--out\\", default=\\"out\\")\\n    ap.add_argument(\\"--sources\\", help=\\"comma-separated subset of source names\\")\\n    ap.add_argument(\\"--offline\\", action=\\"store_true\\", help=\\"use cache only; make no network requests\\")\\n    a = ap.parse_args(argv)\\n    logging.basicConfig(level=logging.INFO, format=\\"%(levelname)s %(message)s\\")\\n    cfg = load_config(a.config)\\n    only = set(a.sources.split(\\",\\")) if a.sources else None\\n    recs, fails, rep = run(cfg, a.out, only, a.offline)\\n    print(json.dumps({\\"records\\": len(recs), \\"by_source\\": rep[\\"by_source\\"], \\"parse_failures\\": len(fails)}, indent=2))\\n    return 0\\n\\n\\nif __name__ == \\"__main__\\":\\n    sys.exit(main())\\n", "src/skillsgap/supply.py": "\\"\\"\\"Supply-side parser: published university graduation lists (PDF) -> programme-level counts.\\n\\nPRIVACY BY DESIGN: graduate names, registration numbers, gender and nationality columns are\\ncounted but NEVER stored. Only (institution, ceremony, award level, programme, count) leaves\\nthis module.\\n\\"\\"\\"\\nimport io\\nimport logging\\nimport re\\n\\nfrom .schema import make_record\\n\\nlog = logging.getLogger(\\"skillsgap.supply\\")\\n\\nAWARD = re.compile(r\\"\\\\b(bachelor|master|doctor|ph\\\\.?d|post\\\\s?graduate|pgd|diploma|certificate)\\\\b\\", re.I)\\nROW = re.compile(r\\"^\\\\s*(\\\\d{1,4})[.)]?\\\\s+[A-Za-z]\\")\\n\\n_LEVELS = [(\\"ph\\", \\"PhD\\"), (\\"doctor\\", \\"PhD\\"), (\\"master\\", \\"Masters\\"), (\\"post\\", \\"Postgraduate diploma\\"),\\n           (\\"pgd\\", \\"Postgraduate diploma\\"), (\\"bachelor\\", \\"Bachelors\\"), (\\"diploma\\", \\"Diploma\\"),\\n           (\\"certificate\\", \\"Certificate\\")]\\n\\n_NON_STEM = re.compile(r\\"business|management|administration|secretarial|education|law|arts|social|\\"\\n                       r\\"journalism|communication|theolog|islamic|shari|human resource|procurement|\\"\\n                       r\\"logistics|finance|banking|public policy|governance|accounting|marketing|\\"\\n                       r\\"monitoring|project planning|library\\", re.I)\\n_STEM = re.compile(r\\"computer|information (technology|systems)|software|engineering|statistics|\\"\\n                   r\\"mathematic|physics|chemistry|biolog|agricultur|environmental science|\\"\\n                   r\\"information security|data|\\\\bscience\\\\b\\", re.I)\\n_REVIEW = re.compile(r\\"medicine|surgery|nursing|biomedical|public health|health|pharmac|dental\\", re.I)\\n\\n\\ndef classify_level(heading):\\n    h = heading.lower()\\n    for key, label in _LEVELS:\\n        if re.search(r\\"\\\\b\\" + re.escape(key), h):\\n            return label\\n    return \\"Other\\"\\n\\n\\ndef classify_field(programme):\\n    \\"\\"\\"PROVISIONAL grouping for the NDPIV STEM:humanities comparison. Health programmes are\\n    flagged REVIEW because the supervisor must confirm whether NDPIV counts them as STEM.\\"\\"\\"\\n    if _REVIEW.search(programme):\\n        return \\"REVIEW_HEALTH\\"\\n    if _NON_STEM.search(programme) and not re.search(r\\"computer|information (technology|systems)|engineering\\", programme, re.I):\\n        return \\"NON_STEM\\"\\n    if _STEM.search(programme):\\n        return \\"STEM\\"\\n    return \\"NON_STEM\\"\\n\\n\\ndef extract_pdf_lines(data):\\n    import pdfplumber\\n    lines = []\\n    with pdfplumber.open(io.BytesIO(data)) as pdf:\\n        for page in pdf.pages:\\n            txt = page.extract_text() or \\"\\"\\n            lines.extend(txt.splitlines())\\n    return lines\\n\\n\\ndef clean_heading(text):\\n    \\"\\"\\"Drop OCR junk at the end of a heading (e.g. \\".\'qt(\'\\" or a stray single lowercase letter).\\"\\"\\"\\n    toks = text.split()\\n    while toks and (not re.fullmatch(r\\"[A-Za-z()&,/-]+\\", toks[-1]) or (len(toks[-1]) == 1 and toks[-1].islower())):\\n        toks.pop()\\n    return \\" \\".join(toks)\\n\\n\\ndef count_programmes(lines):\\n    \\"\\"\\"Walk lines; an award-like heading starts a bucket; numbered rows increment it.\\n    Each bucket is [heading, rows_matched, highest_serial]. The highest serial number is the\\n    better count, because scanned (OCR) lists lose some rows but keep the final serial.\\n    Returns buckets and the number of numbered rows seen before any heading.\\"\\"\\"\\n    buckets, current, orphan_rows = [], None, 0\\n    for line in lines:\\n        s = line.strip()\\n        if not s:\\n            continue\\n        m = ROW.match(s)\\n        if m:\\n            if current is None:\\n                orphan_rows += 1\\n            else:\\n                current[1] += 1\\n                current[2] = max(current[2], int(m.group(1)))\\n            continue\\n        if AWARD.search(s) and len(s) < 140 and not re.search(r\\"\\\\d{4}\\", s[:4]):\\n            h = clean_heading(s)\\n            if h and (current is None or current[1] > 0 or current[0] != h):\\n                current = [h, 0, 0]\\n                buckets.append(current)\\n    return [tuple(b) for b in buckets], orphan_rows\\n\\n\\ndef parse_graduation_pdf(data, meta, retrieved_at, method=\\"http_get\\"):\\n    lines = extract_pdf_lines(data)\\n    buckets, orphan = count_programmes(lines)\\n    records, failures = [], []\\n    for heading, matched, top in buckets:\\n        if matched == 0:\\n            failures.append({\\"url\\": meta[\\"url\\"], \\"reason\\": f\\"heading_without_numbered_rows: {heading[:60]}\\"})\\n            continue\\n        records.append(make_record(\\n            \\"supply\\", meta[\\"name\\"], meta[\\"url\\"], retrieved_at, method,\\n            id_parts=[meta[\\"url\\"], heading], raw_for_hash=f\\"{heading}|{top}\\", record_url=meta[\\"url\\"],\\n            institution=meta[\\"institution\\"], ceremony=meta[\\"ceremony\\"],\\n            award_level=classify_level(heading), programme=heading, graduate_count=max(top, matched),\\n            count_basis=\\"highest_serial_number\\", rows_matched=matched,\\n            field_group_provisional=classify_field(heading)))\\n    if orphan:\\n        failures.append({\\"url\\": meta[\\"url\\"], \\"reason\\": f\\"{orphan} numbered rows before any heading\\"})\\n    if not records:\\n        failures.append({\\"url\\": meta[\\"url\\"], \\"reason\\": \\"no_programme_buckets_parsed (list may be unnumbered or scanned: needs OCR or a custom rule)\\"})\\n    return records, failures\\n", "src/skillsgap/schema.py": "\\"\\"\\"Unified record schema (v0.2, revised after Week 3 labelling) and writers.\\n\\nEvery record carries provenance: source, source_url, record_url, retrieved_at,\\nretrieval_method, pipeline_version, raw_hash, plus a stable record_id.\\nNo personal data is stored: graduation lists are reduced to programme-level counts.\\n\\"\\"\\"\\nimport csv\\nimport hashlib\\nimport json\\nimport re\\nfrom datetime import datetime, timedelta, timezone\\n\\nfrom . import __version__\\n\\nPROVENANCE = [\\"record_id\\", \\"record_type\\", \\"source\\", \\"source_url\\", \\"record_url\\",\\n              \\"retrieved_at\\", \\"retrieval_method\\", \\"pipeline_version\\", \\"raw_hash\\"]\\nDEMAND = [\\"title\\", \\"employer\\", \\"location\\", \\"posted_text\\", \\"posted_date_est\\", \\"function_raw\\",\\n          \\"department\\", \\"ref_no\\", \\"salary_scale\\", \\"vacancies\\", \\"deadline\\", \\"description_raw\\"]\\nSUPPLY = [\\"institution\\", \\"ceremony\\", \\"award_level\\", \\"programme\\", \\"graduate_count\\",\\n          \\"count_basis\\", \\"rows_matched\\", \\"field_group_provisional\\"]\\nFIELDS = PROVENANCE + DEMAND + SUPPLY\\n\\n\\ndef now_iso():\\n    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()\\n\\n\\ndef sha(*parts):\\n    return hashlib.sha256(\\"|\\".join(str(p or \\"\\").strip().lower() for p in parts).encode()).hexdigest()\\n\\n\\ndef make_record(record_type, source, source_url, retrieved_at, method, id_parts, raw_for_hash, **fields):\\n    rec = {k: \\"\\" for k in FIELDS}\\n    rec.update(fields)\\n    rec.update({\\n        \\"record_type\\": record_type, \\"source\\": source, \\"source_url\\": source_url,\\n        \\"retrieved_at\\": retrieved_at, \\"retrieval_method\\": method,\\n        \\"pipeline_version\\": __version__,\\n        \\"record_id\\": f\\"{source}:{sha(*id_parts)[:16]}\\",\\n        \\"raw_hash\\": sha(raw_for_hash),\\n    })\\n    return rec\\n\\n\\n_REL = re.compile(r\\"(\\\\d+)\\\\s+(day|week|month|year)s?\\\\s+ago\\", re.I)\\n\\n\\ndef estimate_posted_date(text, retrieved_iso):\\n    \\"\\"\\"Convert \'Today\', \'Yesterday\', \'4 days ago\' to an ESTIMATED date (precision is coarse).\\"\\"\\"\\n    if not text:\\n        return \\"\\"\\n    base = datetime.fromisoformat(retrieved_iso).date()\\n    t = text.strip().lower()\\n    if t == \\"today\\":\\n        return base.isoformat()\\n    if t == \\"yesterday\\":\\n        return (base - timedelta(days=1)).isoformat()\\n    m = _REL.search(t)\\n    if m:\\n        n, unit = int(m.group(1)), m.group(2).lower()\\n        days = {\\"day\\": 1, \\"week\\": 7, \\"month\\": 30, \\"year\\": 365}[unit] * n\\n        return (base - timedelta(days=days)).isoformat()\\n    return \\"\\"\\n\\n\\ndef write_csv(records, path):\\n    with open(path, \\"w\\", newline=\\"\\", encoding=\\"utf-8\\") as fh:\\n        w = csv.DictWriter(fh, fieldnames=FIELDS, extrasaction=\\"ignore\\")\\n        w.writeheader()\\n        w.writerows(records)\\n\\n\\ndef write_json(records, path):\\n    with open(path, \\"w\\", encoding=\\"utf-8\\") as fh:\\n        json.dump(records, fh, indent=2, ensure_ascii=False)\\n", "config/sources.yaml": "# Source registry. A source runs ONLY if enabled=true AND approval is recorded.\\n# Approval statuses mirror the Week 2 data-source map / compliance log.\\nproject:\\n  user_agent_name: \\"MuniUni-SkillsGapCapstone/0.1\\"\\n  project_url: \\"https://github.com/ayikomike/Skills-Gap-Intelligence-Agent\\"\\n  contact_env: \\"SKILLSGAP_CONTACT_EMAIL\\"\\nhttp:\\n  min_delay_seconds: 3.0       # >= 1 request per 3 s per host\\n  timeout_seconds: 30\\n  max_retries: 3\\n  backoff_base_seconds: 2.0    # waits 2, 4, 8 s (+ jitter)\\n  respect_robots: true\\n  cache_dir: \\"cache\\"\\n  cache_ttl_hours: 24\\nlimits:\\n  max_pages_per_source: 3      # Week 3 test sample only\\n  max_records_per_source: 100\\nsources:\\n  brightermonday:\\n    kind: demand\\n    enabled: true\\n    approval: \\"supervisor-approved (Week 3 brief); no written permission from site owner yet\\"\\n    tos_note: \\"Terms: personal/non-commercial use; research use approved by supervisor. Do not redistribute raw listing text.\\"\\n    listing_url: \\"https://www.brightermonday.co.ug/jobs\\"\\n    fetch_descriptions: false  # set true only after supervisor confirms description capture\\n  district_adverts:\\n    kind: demand\\n    enabled: true\\n    approval: \\"approved: public-sector notices (Week 2, source 3)\\"\\n    urls:\\n      - \\"https://lyantonde.go.ug/node/61\\"\\n  graduation_lists:\\n    kind: supply\\n    enabled: true\\n    approval: \\"approved: published university graduation lists (supervisor advice, Week 3)\\"\\n    lists:\\n      - name: \\"UMI 22nd graduation 2025\\"\\n        institution: \\"Uganda Management Institute\\"\\n        url: \\"https://umi.ac.ug/wp-content/uploads/2025/03/Grad-List-2025.pdf\\"\\n        ceremony: \\"22nd ceremonies, AY 2023/24 (Mar-Apr 2025)\\"\\n        enabled: false   # unnumbered list of names: parser unsupported; use manual seed counts\\n      - name: \\"IUIU 34th graduation (Kampala campus)\\"\\n        institution: \\"Islamic University in Uganda\\"\\n        url: \\"https://www.iuiu.ac.ug/assets/images/home/grad_list/kc.pdf\\"\\n        ceremony: \\"34th ceremony, 20 Dec 2025\\"\\n      - name: \\"IUIU graduation list mc.pdf\\"\\n        institution: \\"Islamic University in Uganda\\"\\n        url: \\"https://www.iuiu.ac.ug/assets/images/home/grad_list/mc.pdf\\"\\n        ceremony: \\"campus and ceremony to be confirmed from the PDF header\\"\\n      - name: \\"IUIU graduation list fc.pdf\\"\\n        institution: \\"Islamic University in Uganda\\"\\n        url: \\"https://www.iuiu.ac.ug/assets/images/home/grad_list/fc.pdf\\"\\n        ceremony: \\"campus and ceremony to be confirmed from the PDF header\\"\\n      - name: \\"Kabale University 11th graduation\\"\\n        institution: \\"Kabale University\\"\\n        url: \\"https://www.kab.ac.ug/?p=27145\\"\\n        ceremony: \\"11th ceremony, 30 Oct 2026\\"\\n        enabled: false   # 31 MB PDF; enable after first run on smaller lists\\n", "tests/test_pipeline.py": "import json, subprocess, sys\\nfrom pathlib import Path\\nimport pytest\\nfrom skillsgap.demand import parse_brightermonday_listing, parse_district_advert\\nfrom skillsgap.schema import estimate_posted_date, FIELDS\\nfrom skillsgap.supply import classify_field, classify_level, parse_graduation_pdf\\nfrom skillsgap.quality import report\\nfrom skillsgap.http import PoliteClient, RobotsDisallowed\\nfrom skillsgap.config import load_config\\n\\nFX = Path(__file__).parent / \\"fixtures\\"\\nTS = \\"2026-10-21T14:00:00+00:00\\"\\n\\n\\ndef test_bm_parser_dedupes_and_flags_missing_employer():\\n    recs, fails = parse_brightermonday_listing((FX / \\"bm_listing.html\\").read_text(), \\"https://x.test/jobs\\", TS)\\n    assert [r[\\"title\\"] for r in recs] == [\\"Operations Manager\\", \\"Stock Controller\\", \\"Marketing Officer\\"]\\n    assert recs[0][\\"employer\\"] == \\"Cook Bright Initiative\\" and recs[0][\\"location\\"] == \\"Kampala\\"\\n    assert recs[1][\\"function_raw\\"] == \\"Supply Chain & Procurement\\"\\n    assert recs[1][\\"posted_date_est\\"] == \\"2026-10-07\\"\\n    assert any(f[\\"reason\\"] == \\"employer_not_found\\" for f in fails)\\n    assert all(r[\\"record_id\\"] and r[\\"raw_hash\\"] and r[\\"retrieved_at\\"] for r in recs)\\n\\n\\ndef test_district_parser_rows_and_deadline():\\n    recs, fails = parse_district_advert((FX / \\"district_advert.html\\").read_text(), \\"https://d.test/n/1\\", TS)\\n    assert len(recs) == 2 and recs[0][\\"deadline\\"] == \\"30th September 2026\\"\\n    assert recs[1][\\"vacancies\\"] == \\"6\\" and any(f[\\"reason\\"] == \\"row_without_title\\" for f in fails)\\n\\n\\ndef test_posted_date_estimates():\\n    assert estimate_posted_date(\\"Today\\", TS) == \\"2026-10-21\\"\\n    assert estimate_posted_date(\\"Yesterday\\", TS) == \\"2026-10-20\\"\\n    assert estimate_posted_date(\\"1 week ago\\", TS) == \\"2026-10-14\\"\\n    assert estimate_posted_date(\\"garbage\\", TS) == \\"\\"\\n\\n\\ndef test_graduation_pdf_counts_and_stores_no_names(tmp_path):\\n    sys.path.insert(0, str(Path(__file__).parent))\\n    from make_pdf_fixture import build\\n    p = tmp_path / \\"g.pdf\\"; build(str(p))\\n    meta = {\\"name\\": \\"TEST\\", \\"url\\": \\"https://t.test/g.pdf\\", \\"institution\\": \\"Test U\\", \\"ceremony\\": \\"1st\\"}\\n    recs, fails = parse_graduation_pdf(p.read_bytes(), meta, TS)\\n    got = {r[\\"programme\\"]: r[\\"graduate_count\\"] for r in recs}\\n    assert got[\\"Bachelor of Science in Computer Science\\"] == 5 and got[\\"Bachelor of Laws\\"] == 3\\n    assert any(\\"Diploma in Business Studies\\" in f[\\"reason\\"] for f in fails)\\n    blob = json.dumps(recs)\\n    assert \\"Testname\\" not in blob and \\"Surname\\" not in blob\\n\\n\\ndef test_classifiers():\\n    assert classify_level(\\"Master of Business Administration\\") == \\"Masters\\"\\n    assert classify_level(\\"Postgraduate Diploma in Finance\\") == \\"Postgraduate diploma\\"\\n    assert classify_field(\\"Bachelor of Science in Computer Science\\") == \\"STEM\\"\\n    assert classify_field(\\"Bachelor of Laws\\") == \\"NON_STEM\\"\\n    assert classify_field(\\"Bachelor of Medicine and Bachelor of Surgery\\") == \\"REVIEW_HEALTH\\"\\n    assert classify_field(\\"Master of Information Technology Management\\") == \\"STEM\\"\\n\\n\\ndef test_quality_report_provenance():\\n    recs, fails = parse_brightermonday_listing((FX / \\"bm_listing.html\\").read_text(), \\"https://x.test/jobs\\", TS)\\n    rep = report(recs, fails)\\n    assert rep[\\"provenance_incomplete\\"] == 0 and rep[\\"by_source\\"][\\"brightermonday\\"] == 3\\n\\n\\nclass FakeResp:\\n    def __init__(self, code, body=b\\"ok\\", headers=None):\\n        self.status_code, self.content, self.headers = code, body, headers or {}\\n        self.text = body.decode()\\n    def raise_for_status(self):\\n        import requests\\n        if self.status_code >= 400: raise requests.HTTPError(str(self.status_code))\\n\\nclass FakeSession:\\n    def __init__(self, seq): self.seq, self.calls, self.headers = list(seq), [], {}\\n    def get(self, url, timeout=None):\\n        self.calls.append(url)\\n        if url.endswith(\\"/robots.txt\\"): return FakeResp(200, b\\"User-agent: *\\\\nDisallow: /private\\\\n\\")\\n        return self.seq.pop(0)\\n\\n\\ndef _client(tmp_path, seq, sleeps):\\n    cfg = load_config(); cfg[\\"http\\"][\\"cache_dir\\"] = str(tmp_path / \\"c\\")\\n    return PoliteClient(cfg, \\"TestUA\\", tmp_path, session=FakeSession(seq), sleep=sleeps.append)\\n\\n\\ndef test_retry_backoff_then_success_and_cache(tmp_path):\\n    sleeps = []\\n    c = _client(tmp_path, [FakeResp(503), FakeResp(200, b\\"hello\\")], sleeps)\\n    body, meta = c.get(\\"https://h.test/a\\")\\n    assert body == b\\"hello\\" and c.stats[\\"retries\\"] == 1 and any(s >= 2 for s in sleeps)\\n    body2, meta2 = c.get(\\"https://h.test/a\\")\\n    assert meta2[\\"from_cache\\"] and c.stats[\\"cache_hits\\"] == 1 and c.stats[\\"requests\\"] == 2\\n\\n\\ndef test_robots_disallow_blocks(tmp_path):\\n    c = _client(tmp_path, [], [])\\n    with pytest.raises(RobotsDisallowed):\\n        c.get(\\"https://h.test/private/x\\")\\n\\n\\ndef test_rate_limit_spaces_requests(tmp_path):\\n    sleeps = []\\n    c = _client(tmp_path, [FakeResp(200, b\\"1\\"), FakeResp(200, b\\"2\\")], sleeps)\\n    c.get(\\"https://h.test/1\\"); c.get(\\"https://h.test/2\\")\\n    assert any(s > 0 for s in sleeps)\\n\\n\\ndef test_end_to_end_run_with_fake_client(tmp_path):\\n    \\"\\"\\"Whole pipeline (extract->transform->load) against fixtures served by a fake client.\\"\\"\\"\\n    import copy\\n    from skillsgap import pipeline\\n    cfg = copy.deepcopy(load_config())\\n    cfg[\\"sources\\"][\\"brightermonday\\"][\\"listing_url\\"] = \\"https://bm.test/jobs\\"\\n    cfg[\\"sources\\"][\\"district_adverts\\"][\\"urls\\"] = [\\"https://d.test/n/1\\"]\\n    cfg[\\"sources\\"][\\"graduation_lists\\"][\\"lists\\"] = []\\n    pages = {\\"https://bm.test/jobs\\": (FX / \\"bm_listing.html\\").read_bytes(),\\n             \\"https://d.test/n/1\\": (FX / \\"district_advert.html\\").read_bytes()}\\n\\n    class FakeClient:\\n        ua = \\"TestUA\\"; stats = {\\"requests\\": 0}\\n        def get(self, url):\\n            if url not in pages: return b\\"<html></html>\\", {\\"from_cache\\": False}\\n            return pages[url], {\\"from_cache\\": False}\\n\\n    recs, fails, rep = pipeline.run(cfg, tmp_path / \\"out\\", client=FakeClient())\\n    assert rep[\\"by_source\\"] == {\\"brightermonday\\": 3, \\"district_adverts\\": 2}\\n    assert rep[\\"provenance_incomplete\\"] == 0\\n    for f in (\\"dataset.csv\\", \\"dataset.json\\", \\"quality_report.json\\", \\"compliance_run_log.csv\\", \\"run_manifest.json\\"):\\n        assert (tmp_path / \\"out\\" / f).exists()\\n    # re-run is idempotent: identical record ids\\n    recs2, _, _ = pipeline.run(cfg, tmp_path / \\"out2\\", client=FakeClient())\\n    assert sorted(r[\\"record_id\\"] for r in recs) == sorted(r[\\"record_id\\"] for r in recs2)\\n\\n\\ndef test_district_text_rows_parsed_from_real_advert_layout():\\n    recs, fails = parse_district_advert((FX / \\"district_advert_text.html\\").read_text(), \\"https://d.test/n/61\\", TS)\\n    assert [r[\\"title\\"] for r in recs] == [\\"District Education Officer\\", \\"Education Assistant II\\",\\n                                          \\"Principal Internal Auditor\\", \\"Senior Accountant\\",\\n                                          \\"Assistant Law Enforcement Officer\\"]\\n    assert recs[1][\\"vacancies\\"] == \\"6\\" and recs[3][\\"ref_no\\"] == \\"LYDSC/4/4/2026\\"\\n    assert recs[0][\\"deadline\\"] == \\"30th September 2026\\" and not fails\\n\\n\\ndef test_highest_serial_beats_matched_rows_and_heading_cleanup():\\n    from skillsgap.supply import count_programmes, clean_heading\\n    lines = [\\"BACHELOR OF LAWS\\", \\"1 A B\\", \\"2 C D\\", \\"garbled line\\", \\"4 E F\\", \\"9 G H\\",\\n             \\"DIPLOMA IN BUSINESS STUDIES t\\", \\"1 X Y\\"]\\n    b, orphan = count_programmes(lines)\\n    assert b[0] == (\\"BACHELOR OF LAWS\\", 4, 9) and b[1][0] == \\"DIPLOMA IN BUSINESS STUDIES\\"\\n    assert clean_heading(\\"BACHELOR OF SCIENCE IN COMPUTER SCIENCE .\'qt(\'\\") == \\"BACHELOR OF SCIENCE IN COMPUTER SCIENCE\\"\\n", "tests/fixtures/district_advert_text.html": "<!-- Text taken from the live Lyantonde advert (tab-separated lines, br-separated) -->\\n<div><p>EXTERNAL ADVERT NO 4 OF 2026</p>\\n<p>Applications are invited ... Not later than 30th September 2026 stating the post applied for and its reference number.<br/>\\nBelow are the details of vacant Posts<br/>\\nS/N\\tDepartment \\t   REF NO\\t         POST TITLE \\t                           SALARY SCALE \\t  NO. OF POSTS<br/>\\n1.     EDUCATION \\t  LYDSC/4/1/2026\\tDistrict Education Officer\\t         U1E\\t               1<br/>\\n2.     EDUCATION     LYDSC/4/2/2026\\tEducation Assistant II\\t                  U7                  \\t6<br/>\\n3.\\tAUDIT\\t          LYDSC/4/3/2026\\tPrincipal Internal Auditor \\t          U2U\\t               1<br/>\\n4.\\tFINANCE\\t  LYDSC/4/4/2026\\tSenior  Accountant\\tU3U\\t1<br/>\\n5. ADMINISTRATION LYDSC/4/5/2026  Assistant Law Enforcement Officer\\t   U5\\t               1<br/>\\n\\tTotal\\t\\t\\t\\t                                                                                                      10<br/>\\nNOTE<br/>Recruitment into public service is free of charge.</p></div>\\n", "scripts/peek_bm.py": "\\"\\"\\"Print the HTML of ONE real BrighterMonday job card (from the cache) so the parser can be fixed.\\nRun from the repo root after a pipeline run:  python scripts/peek_bm.py > out/peek_bm.txt\\"\\"\\"\\nimport base64, glob, json\\nfrom bs4 import BeautifulSoup\\n\\nfor f in glob.glob(\\"cache/*.json\\"):\\n    d = json.load(open(f, encoding=\\"utf-8\\"))\\n    if \\"brightermonday\\" in d[\\"url\\"] and d[\\"url\\"].endswith(\\"/jobs\\"):\\n        soup = BeautifulSoup(base64.b64decode(d[\\"body_b64\\"]).decode(\\"utf-8\\", \\"replace\\"), \\"lxml\\")\\n        for t in soup([\\"script\\", \\"style\\", \\"svg\\", \\"noscript\\"]):\\n            t.decompose()\\n        a = soup.body.select_one(\\"a[href*=\'/listings/\']\\")\\n        card = a\\n        for _ in range(4):\\n            if card.parent is not None and len(card.parent.select(\\"a[href*=\'/listings/\']\\")) <= 2:\\n                card = card.parent\\n        print(\\"anchors with /listings/ in body:\\", len(soup.body.select(\\"a[href*=\'/listings/\']\\")))\\n        print(card.prettify()[:4500])\\n        break\\nelse:\\n    print(\\"BrighterMonday page not found in cache/: run the pipeline first\\")\\n"}')

